<script setup lang="ts">
import {ref} from 'vue';import {checkCloud} from '../../services/cloud';
const name=ref(uni.getStorageSync('recentName')||'我的活动'),names=ref(uni.getStorageSync('recentNames')||'张三\n李四\n王五'),busy=ref(false),error=ref(''),checking=ref(false),connection=ref('尚未验证云服务');
async function connect(){checking.value=true;connection.value='正在检查…';try{await checkCloud();connection.value='云服务连接成功，活动开奖服务尚未启用'}catch(e){const failure=e as {errMsg?:string;message?:string};connection.value='连接失败：'+(failure.errMsg||failure.message||'请稍后重试')}finally{checking.value=false}}
async function create(){busy.value=true;error.value='';try{if(!name.value.trim()||!names.value.trim())throw new Error('请填写活动名称与名单');uni.setStorageSync('recentName',name.value);uni.setStorageSync('recentNames',names.value);uni.showToast({title:'已保存本机草稿',icon:'success'})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script><template><view class="page"><view class="card"><text>活动设置</text><input v-model="name" placeholder="活动名称"/><textarea v-model="names" placeholder="每行一名参与人"/><view class="muted">每行一个名字，同名参与人请添加编号。草稿保存在当前设备。</view></view><button :disabled="busy" @click="create">保存本机草稿</button><view class="muted">{{error}}</view><view class="card"><text>{{connection}}</text><button :disabled="checking" @click="connect">检查云服务</button></view></view></template>
